import {createLiveHeader} from '../live/header.js';
import {SECTORS,TOTAL_TASKS,STEP,END,createCity,tickCity,eligible} from './city-model.js';
import {counts} from './region-model.js';
import {createUrbanWorld} from './urban-world.js';
import {createNarrator} from './narrator.js';
const $=id=>document.getElementById(id),fmt=(n,d=0)=>n.toLocaleString('en-US',{maximumFractionDigits:d});
let state=createCity(),selected=0,playing=false,speed=1,last=performance.now(),clock=0,uiClock=0,motion=0,world;
const live=createLiveHeader({anchor:'.region-layout',kind:'city',onPlay:()=>$('c-play').click(),onReset:()=>$('c-reset').click()});
function updateLive(){const points=[{time:0,total:0,reference:600,fleet:24,referenceFleet:24},...state.history.map(h=>({time:h.time,total:h.covered,reference:600-h.covered,fleet:h.industryFleet,referenceFleet:24}))];const current={time:state.industry.time,total:state.assigned.reduce((a,b)=>a+b,0),fleet:state.industry.fleet,referenceFleet:24};live.update({time:current.time,playing,horizon:END,points:[...points.filter(p=>p.time<current.time),current]});}
const narrator=createNarrator({toggleHost:document.querySelector('.region-top'),onBegin(){playing=false;update();}});
try{world=createUrbanWorld($('c-canvas'));$('c-loading').hidden=true;}catch(e){$('c-loading').textContent='The 3D world could not start. Controls and comparisons remain available.';console.error(e);}
const labels=[],tabs=[],citySites=Array.from({length:36},(_,i)=>({type:Math.floor(i/6),slot:i%6,status:'open',progress:0,workers:0}));
SECTORS.forEach((sector,i)=>{for(const floating of [true,false]){const b=document.createElement('button');b.type='button';b.className=floating?'region-zone':'region-sector';b.innerHTML='<b>'+String(i+1).padStart(2,'0')+'</b><span>'+sector.name+'</span><small></small>';b.setAttribute('aria-label','Select '+sector.name);b.onclick=()=>select(i);(floating?$('c-labels'):$('c-sectors')).append(b);(floating?labels:tabs).push(b);}});
function chart(el,values,max,limit){const h=el.id==='c-chart'?130:100,top=8,bottom=h-8,left=25,right=315;let html='';for(let j=0;j<3;j++){const y=top+(bottom-top)*j/2;html+='<path d="M'+left+' '+y+'H'+right+'" stroke="#607b8d" stroke-opacity=".35"/><text x="0" y="'+(y+3)+'" fill="#8ba8b9" font-size="9">'+Math.round(max*(1-j/2))+'</text>';}
 const humanPoints=[[0,max],...values.map(([x,v])=>[x,max-v])].map(([x,v])=>(left+x/END*(right-left)).toFixed(2)+','+(bottom-v/max*(bottom-top)).toFixed(2)).join(' ');html+='<polyline points="'+humanPoints+'" fill="none" stroke="#efad74" stroke-width="2"/>';const y=bottom-limit/max*(bottom-top);html+='<path d="M'+left+' '+y+'H'+right+'" stroke="#8da5b4" stroke-dasharray="4 4"/>';const points=[[0,0],...values].map(([x,v])=>(left+x/END*(right-left)).toFixed(2)+','+(bottom-v/max*(bottom-top)).toFixed(2)).join(' ');el.innerHTML=html+'<polyline points="'+points+'" fill="none" stroke="#b2e2cf" stroke-width="2.5"/>';}
function update(){updateLive();const t=state.industry.time,covered=state.assigned.reduce((a,b)=>a+b,0),cap=eligible(state),sector=SECTORS[selected],pending=state.pending.reduce((a,b)=>a+b.count,0);
 $('c-cycle').textContent='CYCLE '+String(Math.floor(t)).padStart(2,'0');$('c-state').textContent=playing?'Running':'Paused';$('c-play').textContent=playing?'Ⅱ Pause':t>=END?'↺ Replay':'▶ Play';$('c-progress').style.width=t/END*100+'%';$('c-share-value').textContent=Math.round(state.share*100)+' %';
 $('c-humans').textContent=fmt(TOTAL_TASKS-covered);$('c-robots').textContent=fmt(covered);$('c-percent').textContent=fmt(covered/TOTAL_TASKS*100,1)+'% of the scenario';$('c-industry').textContent=fmt(state.industry.fleet);$('c-facilities').textContent=counts(state.industry).reduce((a,b)=>a+b,0)+' facilities';$('c-queue').textContent=pending+' robots in transit · '+state.available+' available without an assigned task';
 $('c-neighbourhoods').textContent=state.assigned.filter(n=>n>0).length+' / 6';$('c-arrivals').textContent=pending;const previous=state.history.filter(h=>h.time<=t-10).at(-1);$('c-arrival-rate').textContent=fmt(covered-(previous?.covered??0));$('c-milestone').textContent=!covered?'01 · First deliveries':state.assigned.some(n=>n===0)?'02 · New neighbourhoods':covered<cap.reduce((a,b)=>a+b,0)?'03 · Part of everyday life':'04 · Scenario coverage reached';$('c-event').textContent=t>=END?'Scenario complete. Change the hypothesis or compare another distribution.':covered>=cap.reduce((a,b)=>a+b,0)?'This hypothesis has reached its scope. Additional robots wait for new tasks.':covered?'New robots arrive from industry and are allocated automatically.':'The city begins with tasks performed by humans.';
 chart($('c-chart'),state.history.map(h=>[h.time,h.covered]),TOTAL_TASKS,cap.reduce((a,b)=>a+b,0));$('c-chart').setAttribute('aria-label',fmt(covered)+' covered tasks out of '+TOTAL_TASKS);
 $('c-name').textContent=sector.name;$('c-description').textContent=sector.description;$('c-local-humans').textContent=sector.tasks-state.assigned[selected];$('c-local-robots').textContent=state.assigned[selected];$('c-local-bar').style.width=state.assigned[selected]/sector.tasks*100+'%';$('c-local-limit').textContent='This hypothesis allows up to '+cap[selected]+' out of '+sector.tasks+' tasks in this sector to be covered.';chart($('c-sector-chart'),state.history.map(h=>[h.time,h.assigned[selected]]),sector.tasks,cap[selected]);
 for(let i=0;i<6;i++)for(const b of [labels[i],tabs[i]]){b.querySelector('small').textContent=state.assigned[i]+' / '+SECTORS[i].tasks;b.style.setProperty('--coverage',state.assigned[i]/SECTORS[i].tasks*100+'%');b.setAttribute('aria-pressed',String(i===selected));}
}
function select(i,narrate=true){selected=i;world?.select(i*6);update();if(narrate){narrator.explain('city-'+i);if(matchMedia('(max-width:760px)').matches)$('c-inspector').scrollIntoView({block:'start',behavior:'smooth'});}}
function reset(){narrator.stop();state=createCity(Number($('c-scenario').value),Number($('c-share').value)/100);playing=false;clock=0;motion=0;world?.fit();update();}
document.addEventListener('narration-focus',e=>{if(/^city-\d+$/.test(e.detail))select(Number(e.detail.split('-')[1]),false);});
document.addEventListener('click',e=>{if(e.target.closest('#c-play,#c-jump,#c-reset,#c-help'))narrator.stop();},true);
$('c-play').onclick=()=>{if(state.industry.time>=END)reset();playing=!playing;last=performance.now();update();};$('c-reset').onclick=reset;$('c-speed').onchange=e=>speed=Number(e.target.value);$('c-share').oninput=e=>{narrator.stop();state.share=Number(e.target.value)/100;update();};$('c-scenario').onchange=reset;$('c-jump').onclick=()=>{playing=false;for(let i=0;i<10/STEP;i++)tickCity(state);update();};$('c-help').onclick=()=>{playing=false;update();$('c-about').showModal();};$('c-close-help').onclick=()=>$('c-about').close();$('c-minus').onclick=()=>world?.zoomBy(.8);$('c-plus').onclick=()=>world?.zoomBy(1.25);$('c-fit').onclick=()=>world?.fit();
const surface=$('c-canvas'),pointers=new Map();let moved=false,start=null,pinch=0;
surface.addEventListener('pointerdown',e=>{if(e.button!==0)return;surface.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===1){start={x:e.clientX,y:e.clientY};moved=false;}else{moved=true;const [a,b]=[...pointers.values()];pinch=Math.hypot(a.x-b.x,a.y-b.y);}});
surface.addEventListener('pointermove',e=>{const p=pointers.get(e.pointerId);if(!p)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(pinch)world?.zoomBy(d/pinch);pinch=d;moved=true;}else{if(start&&Math.hypot(start.x-e.clientX,start.y-e.clientY)>6)moved=true;if(moved)world?.pan(e.clientX-p.x,e.clientY-p.y);}});
surface.addEventListener('pointerup',e=>{if(!moved&&pointers.size===1){const i=world?.pick(e.clientX,e.clientY)??-1;if(i>=0)select(Math.floor(i/6));}pointers.delete(e.pointerId);pinch=0;});surface.addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);moved=true;pinch=0;});surface.addEventListener('wheel',e=>{e.preventDefault();world?.zoomBy(Math.exp(-e.deltaY*.001));},{passive:false});document.addEventListener('visibilitychange',()=>last=performance.now());
update();function frame(now){const dt=Math.min(.1,(now-last)/1000);last=now;if(!document.hidden){if(playing){clock+=dt*speed;motion+=dt*Math.min(speed,2);while(clock>=STEP&&state.industry.time<END){tickCity(state);clock-=STEP;}if(state.industry.time>=END)playing=false;}uiClock+=dt;if(uiClock>.25){update();uiClock=0;}const group=world?.render({sites:citySites,fleet:TOTAL_TASKS,flow:state.industry.flow,time:state.industry.time,pending:state.pending,cityTasks:SECTORS.map(s=>s.tasks),cityAssigned:state.assigned},motion)??1;$('c-scale').textContent='One figure ≈ '+group+' tasks · orange: humans · light: robots';labels.forEach((b,i)=>{if(!world){b.hidden=true;return;}const p=world.project(i);b.style.left=p.x+'px';b.style.top=p.y+'px';b.hidden=p.x<25||p.x>surface.clientWidth-25||p.y<65||p.y>surface.clientHeight-85;});}requestAnimationFrame(frame);}requestAnimationFrame(frame);
